import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line1 = br.readLine();if (line1 == null) return;StringTokenizer st1 = new StringTokenizer(line1);int n = Integer.parseInt(st1.nextToken());long k = Long.parseLong(st1.nextToken());long[] a = new long[n];String line2 = br.readLine();if (line2 == null) return;StringTokenizer st2 = new StringTokenizer(line2);for (int i = 0; i < n; i++) {a[i] = Long.parseLong(st2.nextToken());}if (n == 1 && k % 2 != 0) {System.out.println(-1);return;}if (k == 1) {System.out.println(a[1]);return;}long maxVal = -1;int limit = (int) Math.min(n, k - 1);for (int i = 0; i < limit; i++) {if (a[i] > maxVal) {maxVal = a[i];}}if (k > n) {System.out.println(maxVal);} else {if (a[limit] > maxVal) {maxVal = a[limit];}System.out.println(maxVal);}}}